// CrapsBattle._BONUS_PERIODS_PER_DAY: six scheduled windows; period 5 is the daily JACKPOT BATTLE.
// The window count is read off the ACTIVE clock's own shape so it can never drift from the schedule
// it is counting: `periodCloseSeconds` names every close but the last one (the jackpot battle is
// not clock-bound), so its length is one short of the window count.
export function crapsBattlesPerDay(clock = CRAPS_SCHEDULE) {
  return clock.periodCloseSeconds.length + 1;
}
// CrapsBattle `_BET_DAYHIGH_MASK` (0x3F): one bit per scheduled window, jackpot period included.
function crapsAllWindowsMask() { return (1 << crapsBattlesPerDay()) - 1; }
/** "six" for user-visible copy naming the whole day's slate. */
