const FLIP_WEI = 10n ** 18n;

/** Available funds are the shared wallet + claimable-winnings disclosure.
 * Auto-rebuy carry is already excluded by its owner. A held/mismatched quote
 * is unknown, so it cannot incorrectly label an account as short of funds. */
export function crapsEntryFundsState({
  costFlip = null,
  address = getActingAddress(),
  canSign = deriveCanSign(),
  disclosure = get('ui.protocolCoinsFlipDisclosure'),
} = {}) {
  const unknown = { state: 'unknown', reason: '' };
  if (!canSign || !address || costFlip == null) return unknown;
  let cost;
  try { cost = BigInt(costFlip); } catch (_) { return unknown; }
  if (cost < 0n) return unknown;
  if (cost === 0n) return { state: 'free', reason: '' };
  if (String(disclosure?.address || '').toLowerCase() !== String(address).toLowerCase()
    || disclosure?.held !== false || disclosure?.valueWei == null) return unknown;
  let available;
  try { available = BigInt(disclosure.valueWei); } catch (_) { return unknown; }
  if (available < 0n) return unknown;
  const required = cost * FLIP_WEI;
  if (available >= required) return { state: 'available', reason: '' };
  const format = value => {
    const whole = (value / FLIP_WEI).toLocaleString('en-US');
    const fraction = (value % FLIP_WEI).toString().padStart(18, '0').replace(/0+$/, '');
    return fraction ? `${whole}.${fraction}` : whole;
  };
  return {
    state: 'insufficient',
    reason: `Not enough FLIP. Requires ${format(required)} FLIP; ${format(available)} FLIP available. Add ${format(required - available)} FLIP.`,
  };
}

/** Exact paid H-1 window delta, with the same newcomer premium as the door. */
export function crapsEntryUpgradePriceFlip({ terms, periodMask, newcomer = false } = {}) {
  if (!Number.isInteger(periodMask) || periodMask <= 0 || periodMask > crapsAllWindowsMask()
    || terms?.highMult == null) return null;
  try {
    let cost = 0n;
    for (let period = 0; period < crapsBattlesPerDay(); period += 1) {
      if (!(periodMask & (1 << period))) continue;
      const base = terms.windows?.[period]?.buyInFlip;
      if (base == null) return null;
      cost += BigInt(base) * BigInt(terms.highMult - 1);
    }
    return cost >= 0n ? crapsEntryPriceFlip(cost, newcomer) : null;
  } catch (_) { return null; }
}
