export const CRAPS_LOBBY_ROW_BUDGET = 9.5;

/**
 * Indexes of visible lobby rows to drop, given the rows in urgency order as
 * 'head' (half a row), 'previous' (the pinned Main Event), 'row', or null.
 * Reserve yesterday and its header before trimming older ordinary history.
 */
export function crapsLobbyTrimmedRows(kinds, budget = CRAPS_LOBBY_ROW_BUDGET) {
  kinds = Array.isArray(kinds) ? kinds : [];
  const trimmed = new Set();
  const pinned = kinds.includes('previous');
  let units = pinned ? kinds.reduce((sum, kind) => sum + (kind === 'previous' ? 2 : kind === 'head' ? 1 : 0), 0) : 0;
  let lastKept = -1;
  kinds.forEach((kind, index) => {
    if (kind == null) return;
    if (pinned && (kind === 'previous' || kind === 'head')) return;
    const weight = kind === 'head' ? 1 : 2;
    if (units + weight > budget * 2) { trimmed.add(index); return; }
    units += weight;
    lastKept = index;
  });
  if (!pinned && lastKept >= 0 && kinds[lastKept] === 'head') trimmed.add(lastKept);
  return trimmed;
}
